import type { Column, Typed } from '../Column'
import type { TableName, TableSchemaDotWalk } from '../Table'

type FieldListElement<T extends TableName = TableName> = TableSchemaDotWalk<T> | (unknown & {})

/**
 * Field list value - supports both type-safe table fields and generic strings.
 * Uses TableSchemaDotWalk for dot-walk notation when table is known.
 */
export type FieldListValue<T extends TableName = TableName> = FieldListElement<T>[]

type FieldListColumnType<
    T extends TableName = TableName,
    Type extends FieldListValue<T> = FieldListValue<T>,
    Default extends Type = Type,
> = Column<Type, Default> & {
    /**
     * Field name (string) of a TableNameColumn within the same table schema.
     * This is metadata indicating which field provides the table context for field list.
     *
     * @example 'referenced_table' - references a TableNameColumn field named 'referenced_table'
     */
    dependent: string
}

/**
 * A Column for a field list type field.
 * Contains a list of field names from a specified table, supporting dot-walk notation.
 * Accepts string values (use fieldList() helper for arrays).
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *   * **dependent**? - field name (string) of a TableNameColumn that provides runtime table context
 *
 * @example
 * ```typescript
 * const displayFields = FieldListColumn({
 *     label: 'Display Fields',
 *     dependent: 'referenced_table',
 *     default: fieldList<'sc_cat_item'>(['name', 'description', 'cost']),
 * })
 * ```
 */
export function FieldListColumn<
    const T extends TableName = TableName,
    const Type extends FieldListValue<T> = FieldListValue<T>,
    const Default extends Type = Type,
    const C extends FieldListColumnType<T, Type, Default> = FieldListColumnType<T, Type, Default>,
>(config: C & FieldListColumnType<T, Type, Default>) {
    return config as Typed<Type, C>
}
